  `status` enum('pending','approved','rejected','archived') NOT NULL DEFAULT 'pending',
  `submitted_by` bigint(20) unsigned DEFAULT NULL,
  `approved_by` bigint(20) unsigned DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `verified_tier` enum('verified','community','imported') NOT NULL DEFAULT 'community',
  `karma_score` int(10) unsigned NOT NULL DEFAULT 0,
  `is_claimed` tinyint(1) NOT NULL DEFAULT 0,
  `claimed_by` bigint(20) unsigned DEFAULT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `website` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `places_slug_unique` (`slug`),
  KEY `places_category_id_status_index` (`category_id`,`status`),
  KEY `places_source_ref_index` (`source_ref`),
  KEY `places_barangay_id_foreign` (`barangay_id`),
